"""DL-NM1 generated byte-copy fixtures; not real cross-host/N1M acceptance."""
import contextlib
import copy
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from scripts import dl_replay_stage as stage
from scripts import dl_normal_replay as replay
from scripts import dl_replay_inventory as inventory


def code_pins():
  return {name:{key:value for key,value in stage.pin(ROOT/name).items()
      if key != 'path'} for name in stage.SOURCES}


def authority(action, host, command, capture, root):
  log = root/(action+'-worker.log')
  if not log.exists():
    log.write_text('Generated fixture, not executed cross-host authority.\n')
  return dict(version=stage.AUTHORITY_VERSION, action=action, actual_hostname=host,
      parent_identity=dict(pid=101, pgid=101, start_ticks=1000),
      worker_identity=dict(pid=102, pgid=102, start_ticks=1001), command=command,
      seconds=900, elapsed_seconds=1., elapsed_scope=stage.AUTHORITY_SCOPE,
      started_utc='2026-10-15T13:00:00+00:00',
      ended_utc='2026-10-15T13:00:01+00:00', started_monotonic=1., ended_monotonic=2.,
      returncode=0, worker_terminal=True, owned_group_cleaned=True,
      cpu_environment=stage.CPU_ENV, failure=None, worker_log=stage.pin(log),
      worker_output=stage.pin(capture))


class ReplayStageTests(unittest.TestCase):
  @classmethod
  def setUpClass(cls):
    # Reuse its real generated three-chunk schema/CRC fixture, never original1M.
    from tests.test_dl_normal_replay import NormalReplayTest
    cls.fixture = NormalReplayTest
    cls.fixture.setUpClass()

  @classmethod
  def tearDownClass(cls):
    cls.fixture.tearDownClass()

  def setUp(self):
    self.temporary = tempfile.TemporaryDirectory(prefix='dl-replay-stage-')
    self.root = Path(self.temporary.name)
    self.stack = contextlib.ExitStack()
    self.addCleanup(self.temporary.cleanup)
    self.addCleanup(self.stack.close)
    self.stack.enter_context(mock.patch.object(stage, 'INVENTORY_SHA', self.fixture.pin))
    self.stack.enter_context(mock.patch.object(stage, 'COUNTS', (3, 1, 120, 3, 117)))
    self.stack.enter_context(mock.patch.object(replay, 'EXPECTED_COUNTS', (3, 1, 120, 3, 117)))
    self.stack.enter_context(mock.patch.object(inventory, 'CHAINS', 1))
    self.stack.enter_context(mock.patch.object(stage, 'binding', side_effect=lambda git:code_pins()))
    self.inventory = self.root/'original-inventory-copy.json'
    self.inventory.write_bytes(self.fixture.report.read_bytes())
    self.source_record = self.root/'source-record.json'
    source_output = self.root/'source-worker-output.json'
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.SOURCE_HOST+'.fixture'):
      source = stage.capture(self.fixture.report, 'd'*40)
    stage.write_json(source_output, source)
    source['authority'] = authority('source', stage.SOURCE_HOST+'.fixture', [
        sys.executable, str(ROOT/'scripts/dl_replay_stage.py'), 'source',
        '--inventory', str(self.fixture.report), '--output', str(source_output),
        '--expected-git', 'd'*40, '--worker'], source_output, self.root)
    stage.write_json(self.source_record, source)
    self.source_sha = stage.sha(self.source_record)
    self.incoming = self.root/'incoming'
    self.incoming.mkdir()
    for original in self.fixture.directory.iterdir():
      shutil.copyfile(original, self.incoming/original.name)
    self.destination = self.root/'materialized'
    self.stage_record = self.root/'stage.json'

  def materialize(self):
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'):
      result = stage.materialize(self.inventory, self.source_record, self.source_sha,
          self.incoming, self.destination, 'e'*40)
    output = self.root/'materialize-worker-output.json'
    stage.write_json(output, result)
    result['authority'] = authority('materialize', stage.TARGET_HOST+'.fixture', [
        sys.executable, str(ROOT/'scripts/dl_replay_stage.py'), 'materialize',
        '--inventory', str(self.inventory), '--source-record', str(self.source_record),
        '--expected-source-record-sha256', self.source_sha, '--incoming', str(self.incoming),
        '--replay-directory', str(self.destination), '--expected-git', 'e'*40,
        '--output', str(output), '--worker'], output, self.root)
    stage.write_json(self.stage_record, result)
    return result

  def load(self, path=None, pin=None):
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'):
      return replay.load_private_cache(self.destination, self.inventory,
          expected_inventory_sha256=self.fixture.pin,
          stage_record_path=path or self.stage_record,
          expected_stage_record_sha256=pin or stage.sha(self.stage_record))

  def rewritten(self, value, suffix):
    path = self.root/(suffix+'.json')
    stage.write_json(path, value)
    return path, stage.sha(path)

  def test_exact_materialization_preserves_original_manifest_and_private_replay(self):
    result = self.materialize()
    self.assertEqual(result['source']['before_inventory'], result['materialized']['after_inventory'])
    self.assertEqual(self.inventory.read_bytes(), self.fixture.report.read_bytes())
    cache = self.load()
    original = self.fixture().load()
    self.assertEqual(cache.make_plan(91, 1), original.make_plan(91, 1))
    starts = self.fixture().starts()
    left, right = cache.read_batch(starts), original.read_batch(starts)
    for key in left:
      self.assertEqual(left[key].tobytes(), right[key].tobytes(), key)
    receipt = cache.receipt()
    self.assertFalse(receipt['original_inventory_authenticated'])  # Explicit small fixture.
    provenance = receipt.pop('stage_provenance')
    self.assertEqual(receipt, original.receipt())
    self.assertEqual(provenance['original_replay_directory'], str(self.fixture.directory))
    self.assertEqual(provenance['materialized_replay_directory'], str(self.destination))
    self.assertFalse(provenance['remote_ssh_execution_independently_proven'])
    self.assertIsNone(cache._pending)
    for name, body in self.fixture.sourcebytes.items():
      self.assertEqual((self.fixture.directory/name).read_bytes(), body)
      self.assertEqual((self.destination/name).read_bytes(), body)

  def test_no_implicit_relocation_or_unpaired_stage_flags_and_wrong_raw_pin(self):
    self.materialize()
    with self.assertRaisesRegex(ValueError, 'provenance/counts'):
      replay.load_private_cache(self.destination, self.inventory,
          expected_inventory_sha256=self.fixture.pin)
    for kwargs in (dict(stage_record_path=self.stage_record),
        dict(expected_stage_record_sha256=stage.sha(self.stage_record))):
      with self.assertRaisesRegex(ValueError, 'supplied together'):
        replay.load_private_cache(self.destination, self.inventory,
            expected_inventory_sha256=self.fixture.pin, **kwargs)
    with mock.patch.object(stage, 'read_json', side_effect=AssertionError('must not decode bad stage')):
      with self.assertRaisesRegex(ValueError, 'raw SHA differs before JSON'):
        self.load(pin='0'*64)
    with mock.patch.object(inventory, 'read_json', side_effect=AssertionError('must not decode bad inventory')):
      with self.assertRaisesRegex(ValueError, 'Inventory raw SHA'):
        replay.load_private_cache(self.destination, self.inventory,
            stage_record_path=self.stage_record, expected_stage_record_sha256=stage.sha(self.stage_record))

  def test_host_path_source_and_process_authority_tamper_are_rejected_before_decode(self):
    valid = self.materialize()
    for issue in ('host', 'directory', 'manifest', 'old-path', 'authority', 'version', 'code'):
      value = copy.deepcopy(valid)
      if issue == 'host': value['materialized']['actual_hostname'] = 'somewhere-else'
      elif issue == 'directory': value['materialized']['replay_directory'] = str(self.incoming)
      elif issue == 'manifest': value['materialized']['after_inventory'][0]['sha256'] = '0'*64
      elif issue == 'old-path': value['source']['replay_directory'] = str(self.destination)
      elif issue == 'authority': value['authority']['returncode'] = 1
      elif issue == 'version': value['version'] = 'old-stage'
      else: value['source_files']['scripts/dl_replay_stage.py']['sha256'] = '0'*64
      path, digest = self.rewritten(value, issue)
      with self.subTest(issue=issue), mock.patch.object(replay, '_decode', side_effect=AssertionError('not decode')):
        with self.assertRaises(ValueError): self.load(path, digest)

  def test_loader_still_hashes_original_npz_before_decode_after_a_valid_stage(self):
    self.materialize()
    path = next(self.destination.iterdir())
    original = path.read_bytes()
    path.write_bytes(original[:-1]+bytes([original[-1]^1]))
    with mock.patch.object(replay, '_decode', side_effect=AssertionError('corrupt NPZ must not decode')):
      with self.assertRaisesRegex(ValueError, 'Source chunk raw hash differs'):
        self.load()
    self.assertEqual((self.fixture.directory/path.name).read_bytes(), original)

  def test_wrong_incoming_extra_files_changed_metadata_and_existing_destination_fail_closed(self):
    path = next(self.incoming.iterdir())
    original = path.read_bytes()
    path.write_bytes(b'changed bytes')
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'):
      with self.assertRaisesRegex(ValueError, 'Incoming original bytes differ'):
        stage.materialize(self.inventory, self.source_record, self.source_sha,
            self.incoming, self.destination, 'e'*40)
    self.assertFalse(self.destination.exists())
    path.write_bytes(original)
    (self.incoming/'extra.npz').write_bytes(b'extra')
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'):
      with self.assertRaisesRegex(ValueError, 'All original staging chunks'):
        stage.materialize(self.inventory, self.source_record, self.source_sha,
            self.incoming, self.destination, 'e'*40)
    (self.incoming/'extra.npz').unlink()
    self.materialize()
    before = stage.snapshot(self.destination)
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'):
      with self.assertRaisesRegex(ValueError, 'Fresh staging output'):
        stage.materialize(self.inventory, self.source_record, self.source_sha,
            self.incoming, self.destination, 'e'*40)
    self.assertEqual(stage.snapshot(self.destination), before)

  def test_failed_copy_retains_partial_and_source_change_never_publishes(self):
    original_open = Path.open
    writes = []
    def fail_second(path, mode='r', *args, **kwargs):
      if path.parent == self.destination and mode == 'xb':
        writes.append(path)
        if len(writes) == 2:
          raise OSError('Synthetic destination write failure')
      return original_open(path, mode, *args, **kwargs)
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.TARGET_HOST+'.fixture'), \
        mock.patch.object(Path, 'open', fail_second):
      with self.assertRaisesRegex(OSError, 'destination write failure'):
        stage.materialize(self.inventory, self.source_record, self.source_sha,
            self.incoming, self.destination, 'e'*40)
    self.assertTrue(self.destination.exists())
    self.assertEqual(len(list(self.destination.iterdir())), 1)
    self.assertFalse(self.stage_record.exists())
    original_snapshot = stage.snapshot
    calls = []
    def changed_after(directory):
      rows = original_snapshot(directory);calls.append(1)
      if len(calls) == 2:
        rows[0]['sha256'] = '0'*64
      return rows
    with mock.patch.object(stage.socket, 'gethostname', return_value=stage.SOURCE_HOST+'.fixture'), \
        mock.patch.object(stage, 'snapshot', side_effect=changed_after):
      with self.assertRaisesRegex(ValueError, 'changed between complete SHA passes'):
        stage.capture(self.fixture.report, 'd'*40)
    for name, body in self.fixture.sourcebytes.items():
      self.assertEqual((self.fixture.directory/name).read_bytes(), body)

  @unittest.skipUnless(sys.platform == 'linux', 'Real owned process-group test requires Linux')
  def test_owned_timeout_cleans_real_cpu_child_without_publishing_stage(self):
    # Isolated process starts with no NumPy/JAX. Only its owned sleeping child
    # is substituted; actual Linux process identity and group cleanup execute.
    script = r"""import json,sys,tempfile,time
from pathlib import Path
from types import SimpleNamespace
from scripts import dl_replay_stage as s
with tempfile.TemporaryDirectory() as d:
    root=Path(d)
    s.host=lambda action:'fixture'
    s.binding=lambda expected:{}
    s.inventory=lambda path:({'run_directory':str(root/'original')},{})
    actual=s.subprocess.Popen
    children=[]
    def sleeper(command,**kwargs):
        p=actual([sys.executable,'-c','import time; time.sleep(60)'],**kwargs)
        children.append(p)
        return p
    s.subprocess.Popen=sleeper
    s.ENTRY_STARTED=time.monotonic()
    s.DEADLINE=s.ENTRY_STARTED+.25
    failed=False
    try:
        s.supervise(SimpleNamespace(action='source',expected_git='d'*40,
            output=str(root/'source.json'),inventory='fixture'))
    except (ValueError,TimeoutError):
        failed=True
    assert failed and len(children)==1 and children[0].poll() is not None
    assert not s.OWNED and not (root/'source.json').exists()
    print(json.dumps({'actual_owned_child_terminal':True,'published':False}))
"""
    result = subprocess.run([sys.executable, '-c', script], cwd=ROOT,
        capture_output=True, text=True, timeout=15,
        env=dict(os.environ, PYTHONPATH=str(ROOT), **stage.CPU_ENV))
    self.assertEqual(result.returncode, 0, result.stdout+result.stderr)
    self.assertTrue(json.loads(result.stdout)['actual_owned_child_terminal'])

  def test_module_import_has_no_numpy_jax_or_environment_side_effects(self):
    script = """import os,sys,json
before=dict(os.environ)
import scripts.dl_replay_stage
assert not any(x=='jax' or x.startswith('jax.') or x=='numpy' or x.startswith('numpy.') for x in sys.modules)
assert dict(os.environ)==before
print(json.dumps({'stdlib_only':True,'environment_unchanged':True}))
"""
    result = subprocess.run([sys.executable, '-c', script], cwd=ROOT,
        capture_output=True, text=True, env=dict(os.environ, PYTHONPATH=str(ROOT)))
    self.assertEqual(result.returncode, 0, result.stdout+result.stderr)
    self.assertTrue(json.loads(result.stdout)['stdlib_only'])


if __name__ == '__main__':
  unittest.main()
